<?php $esc=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); ?>
<div class="page-header"><div><h1><?= $esc($exam['name']) ?></h1><p><?= $esc($exam['code']) ?> · <?= $esc($exam['exam_type']) ?></p></div><a href="/exams" class="btn">Back</a></div>
<div class="card"><div class="form-grid"><div><small>Academic year</small><strong><?= $esc($exam['academic_year_name']) ?></strong></div><div><small>Term</small><strong><?= $esc($exam['term_name']) ?></strong></div><div><small>Dates</small><strong><?= $esc($exam['starts_on']) ?> → <?= $esc($exam['ends_on']) ?></strong></div><div><small>Classes</small><strong><?= (int)$exam['class_count'] ?></strong></div><div><small>Status</small><strong><?= $esc(ucfirst($exam['status'])) ?></strong></div></div><?php if($exam['instructions']): ?><hr><p><?= nl2br($esc($exam['instructions'])) ?></p><?php endif; ?><p><a href="/exams/<?= (int)$exam['id'] ?>/papers" class="btn btn-primary">Configure Papers & Subjects</a> <a href="/exams/<?= (int)$exam['id'] ?>/grading" class="btn">Grading & Results</a><?php if(in_array($exam['status'],['closed','published'],true)): ?> <a href="/exams/<?= (int)$exam['id'] ?>/analytics" class="btn">Analytics</a><?php endif; ?></p></div>
<div class="card"><h2>Workflow</h2><div class="button-group"><?php $next=['draft'=>'scheduled','scheduled'=>'open','open'=>'closed','closed'=>'published']; if(isset($next[$exam['status']])): ?><form method="post" action="/exams/<?= (int)$exam['id'] ?>/status"><input type="hidden" name="csrf_token" value="<?= $esc(csrf_token()) ?>"><input type="hidden" name="status" value="<?= $next[$exam['status']] ?>"><button class="btn btn-primary">Move to <?= $esc(ucfirst($next[$exam['status']])) ?></button></form><?php endif; ?><?php if(in_array($exam['status'],['draft','scheduled'],true)): ?><form method="post" action="/exams/<?= (int)$exam['id'] ?>/status"><input type="hidden" name="csrf_token" value="<?= $esc(csrf_token()) ?>"><input type="hidden" name="status" value="cancelled"><button class="btn">Cancel</button></form><?php endif; ?></div></div>
